// Catalog expansion: SKU-complete datacentre power plant (transformers, MV/LV
// switchgear, UPS + batteries, busway, rack PDUs, ORv3 power shelves, gensets,
// gas turbines, fuel cells) across the major vendors. Ratings/prices are
// approximate published figures; 'unverified' tags where not fully confirmed.
import type { PowerEquip, VendorInfo, Vendor, CatalogBase } from '../types';

type Cx = [string, string, string[]];
const mk = (pt: PowerEquip['powerType'], id: string, name: string, v: Vendor, from: number, price: number, lead: number, kw: number, eff: number, inst: number, c: Cx, tags: string[] = []): PowerEquip =>
  ({ kind: 'power', id, name, vendor: v, availableFrom: from, priceUSD: price, leadTimeMonths: lead, powerType: pt, capacityKW: kw, efficiency: (pt === 'genset' || pt === 'gas-turbine' || pt === 'solar-ppa') && eff < 0.9 ? 0.96 : eff, installMonths: inst, codex: { summary: c[0], explain: c[1], tradeoffs: c[2], tags: ['cat-power', ...tags] } });
const xfmr = (id: string, name: string, v: Vendor, from: number, price: number, lead: number, kw: number, eff: number, c: Cx, inst = 2, tags: string[] = []) => mk('transformer', id, name, v, from, price, lead, kw, eff, inst, c, tags);
const swgr = (id: string, name: string, v: Vendor, from: number, price: number, lead: number, kw: number, eff: number, c: Cx, inst = 3, tags: string[] = []) => mk('switchgear', id, name, v, from, price, lead, kw, eff, inst, c, tags);
const ups = (id: string, name: string, v: Vendor, from: number, price: number, lead: number, kw: number, eff: number, c: Cx, inst = 2, tags: string[] = []) => mk('ups', id, name, v, from, price, lead, kw, eff, inst, c, tags);
const batt = (id: string, name: string, v: Vendor, from: number, price: number, lead: number, kw: number, eff: number, c: Cx, inst = 0.5, tags: string[] = []) => mk('battery', id, name, v, from, price, lead, kw, eff, inst, c, tags);
const bus = (id: string, name: string, v: Vendor, from: number, price: number, lead: number, kw: number, eff: number, c: Cx, inst = 0.5, tags: string[] = []) => mk('busway', id, name, v, from, price, lead, kw, eff, inst, c, tags);
const pdu = (id: string, name: string, v: Vendor, from: number, price: number, lead: number, kw: number, eff: number, c: Cx, inst = 0.1, tags: string[] = []) => mk('pdu', id, name, v, from, price, lead, kw, eff, inst, c, tags);
const shelf = (id: string, name: string, v: Vendor, from: number, price: number, lead: number, kw: number, eff: number, c: Cx, inst = 0.1, tags: string[] = []) => mk('power-shelf', id, name, v, from, price, lead, kw, eff, inst, c, tags);
const genset = (id: string, name: string, v: Vendor, from: number, price: number, lead: number, kw: number, eff: number, c: Cx, inst = 3, tags: string[] = []) => mk('genset', id, name, v, from, price, lead, kw, eff, inst, c, tags);
const turb = (id: string, name: string, v: Vendor, from: number, price: number, lead: number, kw: number, eff: number, c: Cx, inst = 12, tags: string[] = []) => mk('gas-turbine', id, name, v, from, price, lead, kw, eff, inst, c, tags);

